    pub unix_socket: Arc<op_plugins::state_plugins::UnixSocketPlugin>,
}

impl MutationEngine {
    /// Process a D-Bus call through the MutationEngine gate for schema compliance.
    ///
    /// This is the authoritative entry point for all D-Bus MethodCall mutations.
    /// It validates against schema SSOT, ensures compliance via subid_router,
    /// and routes through the mutation chain.
    ///
    /// # Arguments
    /// * `plugin_id` - The plugin identifier from destination path
    /// * `destination` - Full D-Bus object path (/org/opdbus/v1/plugins/<plugin>)
    /// * `path` - Interface path from request
    /// * `interface` - D-Bus interface name
    /// * `method` - Method name to invoke
    /// * `json_body` - Method call arguments
    ///
    /// # Returns
    /// * `Ok(String)` - JSON response from successful mutation
    /// * `Err(anyhow::Error)` - Validation or mutation failure
    pub async fn process_plugin_dbus_call(
        &self,
        plugin_id: String,
        destination: String,
        path: String,
        interface: String,
        method: String,
        json_body: Vec<u8>,
    ) -> anyhow::Result<String> {
        // Validate destination against schema SSOT
        validate_dbus_destination(&destination, &plugin_id, Some(&method))
            .map_err(|e| anyhow::anyhow!("DbusPassthrough validation failed: {}", e))?;

        // Parse path to ensure schema consistency
        let (_, path_segments) = parse_and_validate_dbus_path(
            &destination, &path, &interface, &method
        )?;

        // Convert JSON body to appropriate format for mutation processing
        let json_value: simd_json::OwnedValue = simd_json::from_slice(&json_body)
            .map_err(|e| anyhow::anyhow!("failed to parse json_body: {}", e))?;

        // Route through MutationEngine's authoritative change processing
        // This ensures subid_router compliance gate, event chain recording,
        // and proper mutation broadcasting.
        let mut state_change = op_state_store::StateChange {
            plugin_id: plugin_id.clone(),
            object_path: format!("{}{}", crate::config::PLUGIN_BASE_PATH, destination), // Fully qualified D-Bus path
            change_type: op_state_store::ChangeType::MethodCall,
            member_name: Some(method.clone()),
            old_value: None, // Method calls typically don't have a single old_value
            new_value: json_value.clone(), // Method call arguments become the new_value
            tags_touched: self.compute_tags(&plugin_id, &path).await?,
            event_hash: String::new(), // Will be computed by event chain
            timestamp: chrono::Utc::now(),
            actor_id: plugin_id, // Use plugin_id (extracted from schema), not hardcoded "op-grpc-bridge"
            source: op_state_store::ChangeSource::Grpc, // Source of this mutation
        };

        // Process the authoritative change through MutationEngine
        self.process_authoritative_change(
            state_change.plugin_id.clone(),
            format!("{}{}", crate::config::PLUGIN_BASE_PATH, destination),
            ChangeType::MethodCall,
            Some(method),
            state_change.old_value.clone(),
            json_value.clone(),
            self.compute_tags(&state_change.plugin_id, &path).await?,
            state_change.actor_id.clone(),
            state_change.source,
        ).await.map_err(|e| anyhow::anyhow!("MutationEngine processing failed: {}", e))?;

        // Return a successful response indicating the mutation was processed
        Ok(serde_json::to_string(&serde_json::json!({
            "success": true,
            "plugin": plugin_id,
            "method": method,
            "path": path,
        }))?)
    }
}

impl std::fmt::Debug for MutationEngine {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("MutationEngine").finish()
    }
}

