//! Schema Engine
//!
//! Reads plugin schemas from the shared-memory single-source-of-truth location
//! (`/dev/shm/opdbus/schemas/<plugin_id>.json`). This provides the canonical
//! source for the plugin identity, contract, and available methods for the
//! DbusPassthrough layer.
//!
//! Unlike the SchemaEngine in op-state-store (which is an in-memory catalog),
//! this layer is persistent and authoritative; it is the schema that the
//! DbusPassthrough uses to validate and route calls.

use anyhow::Result;
use std::fs;
use std::path::Path;

/// Reads a plugin schema JSON from the canonical SSOT location.
///
/// # Arguments
/// * `plugin_id` - The plugin identifier (e.g., "zeroclaw", "unix_socket")
///
/// # Returns
/// * `Ok(Some((schema_uuid, schema_subid, schema_json))` - Schema UUID, subid, and content
/// * `Ok(None)` - File does not exist (plugin schema not registered)
/// * `Err` - Failed to read/parse the schema file
pub fn read_plugin_schema_ssot(plugin_id: &str) -> Result<Option<(String, String, String)>> {
    let path = format!("/dev/shm/opdbus/schemas/{}.json", plugin_id);

    if !Path::new(&path).exists() {
        return Ok(None);
    }

    let content = fs::read_to_string(&path)
        .map_err(|e| anyhow::anyhow!("failed to read schema file {}: {}", path, e))?;

    let parsed: serde_json::Value = serde_json::from_str(&content)
        .map_err(|e| anyhow::anyhow!("failed to parse schema JSON in {}: {}", path, e))?;

    // Extract uuid, subid, and full schema from the JSON structure
    let schema_uuid = parsed.get("uuid")
        .and_then(|v| v.as_str())
        .ok_or_else(|| anyhow::anyhow!("schema missing uuid field in {}", path))?,
        .to_string();

    let schema_subid = parsed.get("subid")
        .and_then(|v| v.as_str())
        .ok_or_else(|| anyhow::anyhow!("schema missing subid field in {}", path))?,
        .to_string();

    let schema_json = parsed.get("schema")
        .and_then(|v| v.as_str())
        .ok_or_else(|| anyhow::anyhow!("schema missing schema field in {}", path))?,
        .to_string();

    Ok(Some((schema_uuid, schema_subid, schema_json)))
}

/// Validates a D-Bus destination against the schema-driven legal path.
///
/// # Arguments
/// * `destination` - Full D-Bus object path (e.g., "/org/opdbus/v1/plugins/zeroclaw")
/// * `plugin_id` - Plugin identifier extracted from the destination
/// * `method_name` - Optional method name for additional validation
///
/// # Returns
/// * `Ok(())` - Destination is valid for the schema
/// * `Err` - Destination violates schema constraints
pub fn validate_dbus_destination(
    destination: &str,
    plugin_id: &str,
    method_name: Option<&str>,
) -> anyhow::Result<()> {
    let expected_prefix = "/org/opdbus/v1/plugins/";

    if !destination.starts_with(expected_prefix) {
        return Err(anyhow::anyhow!(
            "illegal destination: must start with '{}', got '{}'",
            expected_prefix,
            destination
        ));
    }

    let dest_plugin_id = &destination[expected_prefix.len()..];
    if dest_plugin_id.is_empty() {
        return Err(anyhow::anyhow!("illegal destination: missing plugin_id in {}", destination));
    }

    // Schema-driven plugin validation
    match read_plugin_schema_ssot(plugin_id) {
        Ok(Some(_)) => {
            // Plugin exists in SSOT - proceed
            if method_name.is_some() {
                tracing::trace!(
                    plugin_id = plugin_id,
                    destination = destination,
                    method_name = method_name.unwrap(),
                    "DbusPassthrough routing validated against schema"
                );
            }
            Ok(())
        }
        Ok(None) => Err(anyhow::anyhow!(
            "illegal destination: no schema found for plugin '{}'",
            dest_plugin_id
        )),
        Err(e) => Err(anyhow::anyhow!(
            "failed to read schema SSOT for '{}': {}",
            dest_plugin_id,
            e
        )),
    }
}

/// Ensures a D-Bus path matches schema-derived nesting.
///
/// # Arguments
/// * `destination` - Full D-Bus object path
/// * `path` - D-Bus interface path from request
/// * `interface` - D-Bus interface name from request
/// * `method_name` - Method name being called
///
/// # Returns
/// * `Ok((plugin_id, path_segments))` - Parsed plugin ID and path segments
/// * `Err` - Path violates schema nesting rules
pub fn parse_and_validate_dbus_path(
    destination: &str,
    path: &str,
    interface: &str,
    method_name: &str,
) -> anyhow::Result<(String, Vec<String>)> {
    let expected_prefix = "/org/opdbus/v1/plugins/";

    if !destination.starts_with(expected_prefix) {
        return Err(anyhow::anyhow!(
            "illegal destination: must start with '{}'",
            expected_prefix
        ));
    }

    let rest = &destination[expected_prefix.len()..];
    let plugin_id = rest
        .split('/')
        .next()
        .ok_or_else(|| anyhow::anyhow!("illegal destination: missing plugin_id"))?
        .to_string();

    if plugin_id.is_empty() {
        return Err(anyhow::anyhow!("illegal destination: empty plugin_id"));
    }

    // Validate path structure is schema-consistent
    let path_segments: Vec<String> = if path == "/" {
        Vec::new()
    } else {
        path[1..].split('/')
            .filter(|s| !s.is_empty())
            .map(|s| s.to_string())
            .collect()
    };

    tracing::debug!(
        destination = destination,
        plugin_id = &plugin_id,
        path = path,
        interface = interface,
        method_name = method_name,
        path_segments = ?&path_segments,
        "DbusPassthrough path parsing completed"
    );

    Ok((plugin_id, path_segments))
}

/// Validates that a D-Bus path represents a schema-declared nested object.
///
/// This function ensures that plugin D-Bus objects follow the schema-defined
/// path structure, which is critical for system consistency and security.
/// 
/// # Arguments
/// * `plugin_id` - Plugin identifier
/// * `path_segments` - Path segments derived from the D-Bus object path
///
/// # Returns
/// * `Ok(())` - Path is valid for the schema
/// * `Err` - Path structure violates schema nesting rules
pub fn validate_dbus_path_structure(
    plugin_id: &str,
    path_segments: &[String],
) -> anyhow::Result<()> {
    // Check if plugin exists in SSOT
    if !plugin_schema_exists(plugin_id) {
        return Err(anyhow::anyhow!(
            "illegal path: plugin schema not found for '{}'",
            plugin_id
        ));
    }

    // Read plugin schema to validate path structure
    match read_plugin_schema_ssot(plugin_id) {
        Ok(Some((schema_uuid, schema_subid, schema_json_str))) => {
            // Schema exists and is valid - proceed
            tracing::trace!(
                plugin_id = plugin_id,
                path_segments = ?path_segments,
                "DbusPassthrough path structure validated against schema SSOT"
            );

            // TODO: Additional schema-driven validation could be added here:
            // - Check if path matches schema-derived object hierarchy
            // - Validate that any nested object types are known to the schema
            // - Ensure constraint rules are enforced

            Ok(())
        }
        Ok(None) => Err(anyhow::anyhow!(
            "illegal path: plugin '{}' does not exist in schema SSOT",
            plugin_id
        )),
        Err(e) => Err(anyhow::anyhow!(
            "failed to validate path for '{}': {}",
            plugin_id,
            e
        )),
    }
}

pub fn resolve_dbus_passthrough_path(
    destination: &str,
    path: &str,
) -> anyhow::Result<String> {
    let (plugin_id, path_segments) = parse_and_validate_dbus_path(
        destination,
        path,
        "", // interface not needed for path resolution
        "", // method not needed for path resolution
    )?;

    // Validate the path structure against plugin schema
    validate_dbus_path_structure(&plugin_id, &path_segments)?;

    // Reconstruct the canonical path for use in D-Bus operations
    let canonical_path = if path_segments.is_empty() {
        destination.to_string()
    } else {
        format!("/{}{}", destination, path)
    };

    tracing::debug!(
        destination = destination,
        path = path,
        plugin_id = &plugin_id,
        canonical_path = &canonical_path,
        "DbusPassthrough path resolved and validated"
    );

    Ok(canonical_path)
}

/// Checks if a plugin schema exists in the SSOT.
///
/// # Arguments
/// * `plugin_id` - Plugin identifier to check
///
/// # Returns
/// * `true` - Schema exists in SSOT
/// * `false` - No schema file found
pub fn plugin_schema_exists(plugin_id: &str) -> bool {
    let schema_path = format!("/dev/shm/opdbus/schemas/{}.json", plugin_id);
    Path::new(&schema_path).exists()
}

/// Resolve a plugin schema and map it to a legal D-Bus path.
///
/// This is the key method that converts plugin schema concepts into the
/// canonical D-Bus path structure, ensuring all projections and mutations
/// follow the legal path. The schema itself is the source of truth for the
/// object tree structure and method signatures.
pub fn resolve_plugin_schema_to_path(plugin_id: &str) -> Result<String, anyhow::Error> {
    // Check if schema exists in SSOT - if not, the plugin doesn't exist
    if !plugin_schema_exists(plugin_id) {
        return Err(anyhow::anyhow!("No schema found for plugin '{}'", plugin_id));
    }

    // Build the canonical D-Bus path based on the schema-driven rules:
    // All plugin D-Bus objects live at /org/opdbus/v1/plugins/{plugin_id}
    // And derive their nested structure from the plugin schema
    let canonical_path = format!("/org/opdbus/v1/plugins/{}", plugin_id);

    tracing::debug!(
        plugin_id = plugin_id,
        canonical_path = &canonical_path,
        "Resolved plugin schema to canonical D-Bus path"
    );

    Ok(canonical_path)
}

